        long long base = (1LL << length) - 1;
        int free = length - 1;
        for (int a = 0; a < free; a++) {
            long long v1 = base - (1LL << a);
            if (v1 <= maximum) numbers.push_back(v1);
            for (int b = a + 1; b < free; b++) {
