import java.io.*;
import java.util.*;

public class Main {
    static byte[] buf;
    static int pos;

    static void skip() {
        while (pos < buf.length && buf[pos] <= ' ') pos++;
    }

    static String next() {
        skip();
        int s = pos;
        while (pos < buf.length && buf[pos] > ' ') pos++;
        return new String(buf, s, pos - s);
    }

    static long nextLong() {
        skip();
        boolean neg = buf[pos] == '-';
        if (neg) pos++;
        long r = 0;
        while (pos < buf.length && buf[pos] > ' ') r = r * 10 + (buf[pos++] - '0');
        return neg ? -r : r;
    }

    static int nextInt() {
        return (int) nextLong();
    }

    static final long MOD = 998244353L;

    static int lowerBound(long[] a, int n, long x) { // first index with a[i] >= x
        int lo = 0, hi = n;
        while (lo < hi) {
            int mid = (lo + hi) >>> 1;
            if (a[mid] < x) lo = mid + 1;
            else hi = mid;
        }
        return lo;
    }

    public static void main(String[] args) throws IOException {
        buf = System.in.readAllBytes();
        int q = nextInt();
        long[] ls = new long[q], rs = new long[q];
        long maximum = 0;
        for (int i = 0; i < q; i++) {
            ls[i] = nextLong();
            rs[i] = nextLong();
            maximum = Math.max(maximum, rs[i]);
        }
        int bits = 64 - Long.numberOfLeadingZeros(maximum);
        // all-ones number of each length with 1..3 non-leading bits cleared
        long[] numbers = new long[600000];
        int count = 0;
        for (int length = 2; length <= bits; length++) {
            long base = (1L << length) - 1;
            int free = length - 1;
            for (int a = 0; a < free; a++) {
                long v1 = base - (1L << a);
                if (v1 <= maximum) numbers[count++] = v1;
                for (int b = a + 1; b < free; b++) {
                    long v2 = v1 - (1L << b);
                    if (v2 <= maximum) numbers[count++] = v2;
                    for (int c = b + 1; c < free; c++) {
                        long v3 = v2 - (1L << c);
                        if (v3 <= maximum) numbers[count++] = v3;
                    }
                }
            }
        }
        Arrays.sort(numbers, 0, count);
        long[] prefix = new long[count + 1]; // prefix sums of cubes mod MOD
        for (int i = 0; i < count; i++) {
            long v = numbers[i] % MOD;
            prefix[i + 1] = (prefix[i] + v * v % MOD * v) % MOD;
        }
        StringBuilder out = new StringBuilder();
        for (int i = 0; i < q; i++) {
            int lo = lowerBound(numbers, count, ls[i]);
            int hi = rs[i] == Long.MAX_VALUE ? count : lowerBound(numbers, count, rs[i] + 1);
            out.append((prefix[hi] - prefix[lo] + MOD) % MOD).append('\n');
        }
        System.out.print(out);
    }
}

package main

import (
	"bufio"
	"io"
	"math/bits"
	"os"
	"sort"
	"strconv"
)

var data []byte
var p int

func next() []byte {
	for p < len(data) && data[p] <= ' ' {
		p++
	}
	s := p
	for p < len(data) && data[p] > ' ' {
		p++
	}
	return data[s:p]
}

func nextInt() int64 {
	t := next()
	neg := len(t) > 0 && t[0] == '-'
	if neg {
		t = t[1:]
	}
	var r int64
	for _, c := range t {
		r = r*10 + int64(c-'0')
	}
	if neg {
		return -r
	}
	return r
}

const mod = 998244353

func main() {
	data, _ = io.ReadAll(os.Stdin)
	q := int(nextInt())
	ls := make([]int64, q)
	rs := make([]int64, q)
	var maximum int64
	for i := 0; i < q; i++ {
		ls[i], rs[i] = nextInt(), nextInt()
		maximum = max(maximum, rs[i])
	}
	length := bits.Len64(uint64(maximum))
	// all-ones number of each length with 1..3 non-leading bits cleared
	numbers := make([]int64, 0, 600000)
	for size := 2; size <= length; size++ {
		base := int64(1)<<size - 1
		free := size - 1
		for a := 0; a < free; a++ {
			v1 := base - int64(1)<<a
			if v1 <= maximum {
				numbers = append(numbers, v1)
			}
			for b := a + 1; b < free; b++ {
				v2 := v1 - int64(1)<<b
				if v2 <= maximum {
					numbers = append(numbers, v2)
				}
				for c := b + 1; c < free; c++ {
					v3 := v2 - int64(1)<<c
					if v3 <= maximum {
						numbers = append(numbers, v3)
					}
				}
			}
		}
	}
	sort.Slice(numbers, func(i, j int) bool { return numbers[i] < numbers[j] })
	prefix := make([]int64, len(numbers)+1) // prefix sums of cubes mod
	for i, x := range numbers {
		v := x % mod
		prefix[i+1] = (prefix[i] + v*v%mod*v) % mod
	}
	w := bufio.NewWriter(os.Stdout)
	defer w.Flush()
	for i := 0; i < q; i++ {
		lo := sort.Search(len(numbers), func(j int) bool { return numbers[j] >= ls[i] })
		hi := sort.Search(len(numbers), func(j int) bool { return numbers[j] > rs[i] })
		w.WriteString(strconv.FormatInt((prefix[hi]-prefix[lo]+mod)%mod, 10))
		w.WriteByte('\n')
	}
}
